import{_ as s,a as e}from"./chunks/about-dialog.CFAf7REh.js";import{_ as i,o as n,c as t,a2 as l}from"./chunks/framework.Dx-TCpNt.js";const b=JSON.parse('{"title":"インストールと起動","description":"KomaYomi は、ローカルの Node サーバーが支えるブラウザアプリとしても、Electron のデスクトップウィンドウとしても動作します。どちらも同じサーバーコードと同じデータディレクトリを使います。","frontmatter":{"description":"KomaYomi は、ローカルの Node サーバーが支えるブラウザアプリとしても、Electron のデスクトップウィンドウとしても動作します。どちらも同じサーバーコードと同じデータディレクトリを使います。"},"headers":[],"relativePath":"ja/guide/installation.md","filePath":"ja/guide/installation.md","lastUpdated":1794842245000}'),d={name:"ja/guide/installation.md"};function o(p,a,r,c,h,u){return n(),t("div",null,[...a[0]||(a[0]=[l(`<h1 id="インストールと起動" tabindex="-1">インストールと起動 <a class="header-anchor" href="#インストールと起動" aria-label="Permalink to &quot;インストールと起動&quot;">​</a></h1><p>KomaYomi は、<strong>ローカルの Node サーバーが支えるブラウザアプリ</strong>としても、<strong>Electron のデスクトップウィンドウ</strong>としても動作します。どちらも同じサーバーコードと同じデータディレクトリを使います。</p><h2 id="解決する課題" tabindex="-1">解決する課題 <a class="header-anchor" href="#解決する課題" aria-label="Permalink to &quot;解決する課題&quot;">​</a></h2><p>アプリを自分のマシンで動かし、自分のフォルダーを読み、アカウントもアップロードも不要にしたい。このページでは、クローン直後から最初のページを開くまでの手順と、デスクトップ版とブラウザ版の違いを説明します。</p><h2 id="要件" tabindex="-1">要件 <a class="header-anchor" href="#要件" aria-label="Permalink to &quot;要件&quot;">​</a></h2><ul><li><strong>Node.js 20 以上</strong>（サーバーバンドルの対象は Node 20 で、リポジトリは Node 22+ で開発されています）。</li><li>npm（Node に同梱）。</li><li>任意: Electron の依存関係は <code>npm install</code> の一部としてインストールされます。</li></ul><p>ホストされたサービスもアカウントもありません。アプリは <code>127.0.0.1</code> でのみ待ち受けます。</p><h2 id="インストール" tabindex="-1">インストール <a class="header-anchor" href="#インストール" aria-label="Permalink to &quot;インストール&quot;">​</a></h2><p>リポジトリのルートで:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span></code></pre></div><h2 id="開発モードで起動" tabindex="-1">開発モードで起動 <a class="header-anchor" href="#開発モードで起動" aria-label="Permalink to &quot;開発モードで起動&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p><code>http://127.0.0.1:5173</code> で Vite が起動します（5173 が使用中ならポートが変わります）。API は Vite のミドルウェアプラグインが提供するため、2つ目のプロセスを起動する必要はありません。</p><h2 id="デスクトップアプリとして起動" tabindex="-1">デスクトップアプリとして起動 <a class="header-anchor" href="#デスクトップアプリとして起動" aria-label="Permalink to &quot;デスクトップアプリとして起動&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> desktop</span></span></code></pre></div><p>このコマンドは3つのことを行います:</p><ol><li><code>npm run build</code> — 型チェックを行い、フロントエンドを <code>dist/</code> にビルドします。</li><li><code>npm run server:build</code> — esbuild でサーバーを <code>dist-server/app.mjs</code> にバンドルします。</li><li><code>electron .</code> — ローカル HTTP サーバーからバンドル済みの静的ファイルを読み込むウィンドウを開きます。</li></ol><p>デスクトップのデータディレクトリ:</p><ul><li>ソースから実行する場合（<code>npm run desktop</code>）、リポジトリのフォルダを使い、<code>raw/</code>、<code>data/</code>、<code>exports/</code> をコードの隣に保ちます。</li><li>パッケージ済みビルドでは、Electron の <code>userData</code> ディレクトリ内の <code>library</code> フォルダが既定となり、初回起動時にフォルダの選択を求めます。</li><li><code>Ctrl+Shift+D</code> でデータディレクトリを切り替えます（再起動が必要です）。</li><li>環境変数 <code>MANGA_DATA_DIR</code> はデータディレクトリを上書きします。</li><li><code>MANGA_PORT</code> は内部ポートを固定します。指定しない場合は空きポートが選ばれます。</li></ul><h2 id="デスクトップビルドのパッケージ化" tabindex="-1">デスクトップビルドのパッケージ化 <a class="header-anchor" href="#デスクトップビルドのパッケージ化" aria-label="Permalink to &quot;デスクトップビルドのパッケージ化&quot;">​</a></h2><p>リポジトリには <code>electron-builder.yml</code> と2つのパッケージングスクリプトが含まれています:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dist:win</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # Windows x64: NSIS インストーラー + ポータブル .exe を release/ に出力</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dist:dir</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # release/ に展開済みアプリを出力。簡単なスモークテストに便利</span></span></code></pre></div><p><code>dist:win</code> はまずフロントエンドとバンドル済みサーバーをビルドし、その後 <code>nsis</code> と <code>portable</code> の両ターゲットで electron-builder を実行します。成果物は <code>KomaYomi-&lt;version&gt;-&lt;arch&gt;.exe</code> と <code>KomaYomi-&lt;version&gt;-portable.exe</code> の命名に従います。</p><p>パッケージに含まれるもの:</p><ul><li><code>dist/</code>、<code>dist-server/</code>、<code>electron/</code>、<code>package.json</code> のみです。<code>node_modules</code> は同梱されません。</li><li><code>raw/</code>、<code>data/</code>、<code>exports/</code> は<strong>同梱されません</strong>。パッケージ済みビルドは初回起動時にライブラリフォルダの選択を求め、それを記憶します。</li></ul><p>現在の制約:</p><ul><li>設定済みのターゲットは Windows x64 のみで、macOS や Linux のパッケージングはありません。</li><li>インストーラーは署名されていないため、初回起動時に Windows SmartScreen が警告を表示する可能性があります。</li><li>このリポジトリではまだパッケージングが最後まで実行されていません。最初の <code>npm run dist:win</code> の出力は、スモークテストするまで<strong>未検証</strong>として扱ってください。</li><li>自動更新チャネルはありません。</li></ul><h2 id="ビルド成果物" tabindex="-1">ビルド成果物 <a class="header-anchor" href="#ビルド成果物" aria-label="Permalink to &quot;ビルド成果物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>コマンド</th><th>出力</th><th>用途</th></tr></thead><tbody><tr><td><code>npm run build</code></td><td><code>dist/</code></td><td>静的フロントエンド。</td></tr><tr><td><code>npm run server:build</code></td><td><code>dist-server/app.mjs</code></td><td>Electron が使うバンドル済み Node サーバー。</td></tr><tr><td><code>npm run dist:dir</code></td><td><code>release/</code></td><td>スモークテスト用の展開済み Electron アプリ。</td></tr><tr><td><code>npm run dist:win</code></td><td><code>release/</code></td><td>Windows x64 の NSIS インストーラーとポータブル <code>.exe</code>（未検証）。</td></tr><tr><td><code>npm run preview</code></td><td>—</td><td>ビルド済みフロントエンドを Vite preview で配信します。API ミドルウェアは開発サーバーの機能なので、API にアクセスするにはデスクトップアプリか <code>npm run dev</code> を使ってください。</td></tr><tr><td><code>npm run typecheck</code></td><td>—</td><td>TypeScript のプロジェクトチェック。</td></tr></tbody></table><h2 id="データディレクトリの構成" tabindex="-1">データディレクトリの構成 <a class="header-anchor" href="#データディレクトリの構成" aria-label="Permalink to &quot;データディレクトリの構成&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>raw/                       # your images (gitignored)</span></span>
<span class="line"><span>  &lt;volume&gt;/&lt;language&gt;/&lt;chapter&gt;/01.jpg</span></span>
<span class="line"><span>data/</span></span>
<span class="line"><span>  pages/&lt;volume&gt;/&lt;chapter&gt;/0.json     # one page JSON, 0-based index</span></span>
<span class="line"><span>  templates/                          # panel templates and export templates</span></span>
<span class="line"><span>  presets/                            # alignment presets</span></span>
<span class="line"><span>  layouts/*.json                      # declarative layout templates</span></span>
<span class="line"><span>  library.json                        # manual language-directory mapping</span></span>
<span class="line"><span>  cache/thumbs/                       # thumbnail cache (safe to delete)</span></span>
<span class="line"><span>  backups/                            # project import backups (gitignored)</span></span>
<span class="line"><span>exports/                   # generated HTML, PNG, backups, .mnproj (gitignored)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p><code>npm run dev</code> は画像を <code>/raw/...</code>、生成ファイルを <code>/exports/...</code> 経由で配信します。どちらのフォルダも静的ディレクトリ一覧としては公開されません。</p><h2 id="ポートとホスト" tabindex="-1">ポートとホスト <a class="header-anchor" href="#ポートとホスト" aria-label="Permalink to &quot;ポートとホスト&quot;">​</a></h2><ul><li>開発 UI: <code>127.0.0.1:5173</code>。</li><li>ドキュメントサイト（このサイト）: <code>docs/</code> から起動した場合 <code>127.0.0.1:5174</code>。</li><li>Electron ウィンドウは一時的な localhost ポートと通信します。</li></ul><figure class="shot"><img src="`+s+'" alt="初回起動の空のライブラリ。サイドバーに「＋ 漫画を追加」、中央に 4 ステップの案内"><figcaption>初回起動でライブラリが空の状態。「＋ 漫画を追加」が入口で、中央の 4 枚のカードが流れを説明します。</figcaption></figure><h2 id="初回起動" tabindex="-1">初回起動 <a class="header-anchor" href="#初回起動" aria-label="Permalink to &quot;初回起動&quot;">​</a></h2><ol><li><code>raw/&lt;volume&gt;/&lt;ja|zh|en&gt;/&lt;chapter&gt;/&lt;pages&gt;</code> に従って、少なくとも1巻を <code>raw/</code> に置きます。</li><li>アプリを開きます。サイドバーに巻と話が一覧表示されます。</li><li>ページを選択します。初回に開くとページが自動検出され、保存されます。</li><li>言語フォルダが認識されない場合は、巻の設定を開いてディレクトリを手動で対応付けてください。</li><li>上部バーの<strong>バージョン情報</strong>を押し、バージョンと現在のデータディレクトリを確認してから不具合を報告してください。</li></ol><figure class="shot"><img src="'+e+`" alt="バージョン情報ダイアログ。KomaYomi のバージョン、ビルド情報、データディレクトリのパス"><figcaption>バージョン情報ダイアログ。不具合を報告するときは、まずバージョンとデータディレクトリを伝えてください。</figcaption></figure><p>命名規則とスキャナーが受け付ける言語の別名は <a href="/KomaYomi-docs/ja/guide/gallery">ライブラリと取り込み</a> を参照してください。</p><h2 id="よくある落とし穴" tabindex="-1">よくある落とし穴 <a class="header-anchor" href="#よくある落とし穴" aria-label="Permalink to &quot;よくある落とし穴&quot;">​</a></h2><ul><li><strong>5173 ポートが使用中。</strong> Vite は次の空きポートに移ります。端末に表示された URL を確認し、5173 と決め打ちしないでください。</li><li><strong>サイドバーが空。</strong> <code>raw/</code> に巻がないか、フォルダー名が認識されていません。<a href="/KomaYomi-docs/ja/guide/gallery">ライブラリと取り込み</a> を参照してください。</li><li><strong>パッケージ版がフォルダー選択を求める。</strong> 正常です。パッケージには <code>raw/</code>、<code>data/</code>、<code>exports/</code> が含まれません。</li><li><strong>データディレクトリを変えても反映されない。</strong> <code>Ctrl+Shift+D</code> で切り替えたあと再起動が必要です。即時反映はされません。</li><li><strong><code>npm run preview</code> では API がない。</strong> ミドルウェアは開発サーバーとデスクトップ版だけにあり、プレビューでは画像を読み込めません。</li><li><strong><code>dist:win</code> は未検証。</strong> 最初のパッケージングはスモークテストとして扱い、クリーンな環境でインストーラーの挙動を記録してください。</li></ul><h2 id="ドキュメントサイト" tabindex="-1">ドキュメントサイト <a class="header-anchor" href="#ドキュメントサイト" aria-label="Permalink to &quot;ドキュメントサイト&quot;">​</a></h2><p>ドキュメントは <code>docs/</code> にあり、独自の依存関係を持ちます:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:dev</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # http://127.0.0.1:5174</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:build</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # static output in docs/.vitepress/dist</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:preview</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # preview the production build</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>リポジトリのルートからは <code>npm --prefix docs run docs:dev</code> も使えます。</p>`,45)])])}const m=i(d,[["render",o]]);export{b as __pageData,m as default};
